
<?php if($intake): ?><section class="card section intake28"><h2>نسخهٔ مسئله هنگام ثبت درخواست</h2><?php foreach(\Morshed\Product\PersonalProblems::FIELDS as $key=>$title): ?><h3><?= $this->h($title) ?></h3><p><?= $this->h($intake['snapshot'][$key]??'') ?></p><?php endforeach; ?><?php if(!empty($intake['snapshot']['organization_name'])): ?><p>مجموعهٔ مرتبط: <?= $this->h($intake['snapshot']['organization_name']) ?></p><?php endif; ?><div class="row"><?php foreach($intake['snapshot']['term_labels']??[] as $t): ?><a class="tag" href="<?= $this->h($this->url('/experiences?'.$t['kind'].'='.$t['id'])) ?>"><?= $this->h($t['title']) ?></a><?php endforeach; ?></div><?php foreach($intake['snapshot']['experience_labels']??[] as $exp): ?><a class="textlink" href="<?= $this->h($this->url('/experience?id='.$exp['id'])) ?>"><?= $this->h($exp['title']) ?></a><?php endforeach; ?><?php if($intake['clarification']): ?><h3>آخرین توضیح تکمیلی مخاطب</h3><p><?= $this->h($intake['clarification']) ?></p><?php endif; ?><?php if($intake['needs_details']): ?><p class="notice">درخواست منتظر توضیح تکمیلی است؛ اعتبار تازه‌ای رزرو نمی‌شود و مهلت پاسخ اصلی حفظ می‌شود.</p><?php endif; ?><?php if(!empty($intake['referred_mentor_id'])): ?><a class="secondary" href="<?= $this->h($this->url('/mentor/profile?id='.$intake['referred_mentor_id'])) ?>">مشاهدهٔ مرشد پیشنهادی</a><?php endif; ?></section>
<?php if(!$admin&&$booking['state']==='pending'&&(int)$booking['expires_at']>time()): ?><?php if($booking['mentor_id']===$this->actor['user_id']): ?><section class="card section intake28"><h2>پاسخ به مسئلهٔ مخاطب</h2><?= $this->start('/booking/reply') ?><input type="hidden" name="id" value="<?= $this->h($booking['id']) ?>"><label>پاسخ<select name="code" required><?php foreach($replies as $reply):if($reply['code']==='accept')continue; ?><option value="<?= $this->h($reply['code']) ?>"><?= $this->h($reply['title']) ?></option><?php endforeach; ?></select></label><label>توضیح اختیاری<textarea name="note" rows="3" maxlength="2000"></textarea></label><label>مرشد دیگر (فقط برای ارجاع)<select name="referred_mentor"><option value="">انتخاب نشده</option><?php foreach($referredMentors as $m): ?><option value="<?= $this->h($m['user_id']) ?>"><?= $this->h($m['display_name']) ?></option><?php endforeach; ?></select></label><button>ارسال پاسخ</button></form><p class="small muted">درخواست توضیح، درخواست را باز نگه می‌دارد. سایر پاسخ‌ها درخواست فعلی را می‌بندند و اعتبار آزاد می‌شود. پذیرش زمان از دکمهٔ «تأیید جلسه» انجام می‌شود.</p></section><?php elseif($intake['needs_details']): ?><section class="card section intake28"><h2>تکمیل توضیحات همان درخواست</h2><?= $this->start('/booking/clarify') ?><input type="hidden" name="id" value="<?= $this->h($booking['id']) ?>"><label>توضیحات تکمیلی<textarea name="clarification" rows="4" required maxlength="6000"></textarea></label><button>ارسال توضیح بدون رزرو اعتبار جدید</button></form></section><?php endif; ?><?php endif; ?><?php endif; ?>
<?php if(!$admin&&(int)$booking['starts_at']<=time()): ?><details class="card section intake28"><summary>گزارش حضور، مشکل فنی یا تخلف برای بررسی مدیر</summary><?= $this->start('/behavior/report') ?><input type="hidden" name="booking_id" value="<?= $this->h($booking['id']) ?>"><label>گزارش دربارهٔ<select name="user_id"><option value="<?= $this->h($booking['user_id']) ?>"><?= $this->h($booking['user_name']) ?></option><option value="<?= $this->h($booking['mentor_id']) ?>"><?= $this->h($booking['mentor_name']) ?></option></select></label><label>نوع گزارش<select name="event"><option value="no_show">غیبت بدون اطلاع</option><option value="late">تأخیر</option><option value="technical">مشکل فنی</option><option value="misconduct">تخلف</option></select></label><label>شرح اتفاق<textarea name="note" required maxlength="4000" rows="3"></textarea></label><label>مدرک یا اطلاعات قابل بررسی<textarea name="evidence" maxlength="4000" rows="3"></textarea></label><button>ثبت برای رسیدگی انسانی</button></form></details><?php endif; ?>
